import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

// Tauri fronts the Vite dev server. Use a dedicated port (5273) so it never
// collides with the extension's own tooling when both run in the monorepo.
export default defineConfig({
  plugins: [react()],
  clearScreen: false,
  server: {
    port: 5273,
    strictPort: true,
    watch: {
      ignored: ["**/src-tauri/**"],
    },
  },
  envPrefix: ["VITE_", "TAURI_"],
  build: {
    target: "esnext",
    minify: !process.env.TAURI_DEBUG ? "esbuild" : false,
    sourcemap: !!process.env.TAURI_DEBUG,
  },
});

import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import OverlayWindow from "./views/OverlayWindow";
import UpdaterWindow from "./views/UpdaterWindow";
import AboutWindow from "./views/AboutWindow";
import "./index.css";

// One bundle serves every window; each secondary window renders its own
// standalone UI keyed by window label (no IPC, no permission needed).
function currentLabel(): string {
  try {
    const internals = (window as unknown as {
      __TAURI_INTERNALS__?: { metadata?: { currentWindow?: { label?: string } } };
    }).__TAURI_INTERNALS__;
    return internals?.metadata?.currentWindow?.label ?? "main";
  } catch {
    return "main";
  }
}

function Root() {
  switch (currentLabel()) {
    case "overlay": return <OverlayWindow />;   // capture HUD (region/window pick)
    case "updater": return <UpdaterWindow />;
    case "about":   return <AboutWindow />;
    default:        return <App />;
  }
}

ReactDOM.createRoot(document.getElementById("root") as HTMLElement).render(
  <React.StrictMode>
    <Root />
  </React.StrictMode>,
);

import { useEffect, useState } from "react";
import { listen } from "@tauri-apps/api/event";
import { exit } from "@tauri-apps/plugin-process";
import Sidebar, { type View } from "./components/Sidebar";
import StatusBar from "./components/StatusBar";
import HomeView from "./views/HomeView";          // shows hotkey + 'Capture now' button
import SettingsView from "./views/SettingsView";  // accounts, hotkey, capture mode, AI (separate subsystem)
import AnnotateView from "./views/AnnotateView";  // hosts the reused canvas editor (separate subsystem)
import { openAboutWindow } from "./lib/api";
import type { CaptureResult } from "./lib/api";

export default function App() {
  const [view, setView] = useState<View>("home");
  const [shot, setShot] = useState<CaptureResult | null>(null);

  const onSelect = (v: View) => {
    if (v === "about") openAboutWindow().catch(() => {});
    else setView(v);
  };

  // Rust emits this after the HUD finishes a crop (or after a Wayland
  // capture-then-crop). Carries the PNG data URL + source geometry.
  useEffect(() => {
    const un = listen<CaptureResult>("capture://annotate", (e) => {
      setShot(e.payload);
      setView("annotate");
    });
    return () => { un.then((f) => f()); };
  }, []);

  // Match curvault: hold the main-window close in Rust, animate <body>, exit.
  useEffect(() => {
    const un = listen("app://close", () => {
      document.body.classList.add("app-closing");
      setTimeout(() => { exit(0).catch(() => {}); }, 230);
    });
    return () => { un.then((f) => f()); };
  }, []);

  return (
    <>
      <div className="titlebar" data-tauri-drag-region></div>
      <div className="app-body">
        <Sidebar current={view} onSelect={onSelect} />
        <div className="main-frame">
          <div className="content">
            {view === "home" && <HomeView onCaptureDone={(s) => { setShot(s); setView("annotate"); }} />}
            {view === "settings" && <SettingsView />}
            {view === "annotate" && <AnnotateView shot={shot} onDone={() => { setShot(null); setView("home"); }} />}
          </div>
          <StatusBar />
        </div>
      </div>
    </>
  );
}

// Single chokepoint for Tauri command invocations (curvault convention:
// components never import @tauri-apps/api directly).
import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";

// ---------- Capture ----------

export interface DisplayInfo { id: number; name: string; x: number; y: number; width: number; height: number; scale: number; isPrimary: boolean; }
export interface WindowInfo { id: number; title: string; appName: string; x: number; y: number; width: number; height: number; }

/** A finished capture handed to the annotate stage. `pngDataUrl` is a
 *  data:image/png;base64 string produced in Rust (xcap -> image -> base64). */
export interface CaptureResult { pngDataUrl: string; width: number; height: number; scale: number; sourceDisplayId: number | null; }

/** Grab the full screen the cursor is currently on (the hotkey entry point). */
export const captureScreenUnderCursor = (): Promise<CaptureResult> => invoke("capture_screen_under_cursor");
export const listDisplays = (): Promise<DisplayInfo[]> => invoke("list_displays");
export const listWindows = (): Promise<WindowInfo[]> => invoke("list_windows");
export const captureWindow = (windowId: number): Promise<CaptureResult> => invoke("capture_window", { windowId });

/** macOS only: is Screen Recording (TCC) granted? UI uses this to guide the
 *  one-time grant + restart instead of capturing a black frame. */
export const macScreenRecordingAuthorized = (): Promise<boolean> => invoke("mac_screen_recording_authorized");

// ---------- Capture HUD overlay window ----------

/** Open the borderless/transparent/always-on-top HUD over the given display,
 *  seeded with a frozen frame. On native Wayland this is a no-op (returns
 *  false) and the caller falls back to in-window crop. */
export const openOverlay = (displayId: number): Promise<boolean> => invoke("open_overlay", { displayId });
export const closeOverlay = (): Promise<void> => invoke("close_overlay");

// ---------- Global hotkey ----------

export const getHotkey = (): Promise<string> => invoke("get_hotkey");
/** Re-register the global shortcut (e.g. "CommandOrControl+Shift+2"). */
export const setHotkey = (accelerator: string): Promise<void> => invoke("set_hotkey", { accelerator });

// ---------- Updates / windows (copied from curvault) ----------

export interface UpdateInfo { currentVersion: string; latestVersion: string; isOutdated: boolean; releaseUrl: string; releaseNotes: string; publishedAt: string | null; }
export const checkForUpdates = (): Promise<UpdateInfo> => invoke("check_for_updates");
export const openUpdaterWindow = (): Promise<void> => invoke("open_updater_window");
export const openAboutWindow = (): Promise<void> => invoke("open_about_window");

// ---------- Events ----------

/** Fired by Rust when the global hotkey is pressed (frontend may show a
 *  pre-capture hint); the actual capture is driven from Rust. */
export const onHotkey = (cb: () => void): Promise<UnlistenFn> => listen("hotkey://fired", () => cb());

// Prevents an extra console window on Windows in release.
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

fn main() {
    shot2issue_lib::run()
}

mod commands;
mod services; // services/{capture,hotkey,updates,tray}.rs — sibling subsystems

use tauri::{Emitter, Manager, WindowEvent};

/// Open (or focus) a frameless rounded popup (updater / about) — copied from
/// curvault. The webview branches on window label (see main.tsx).
pub(crate) fn open_popup<R: tauri::Runtime>(app: &tauri::AppHandle<R>, label: &str, title: &str, w: f64, h: f64) {
    use tauri::{WebviewUrl, WebviewWindowBuilder};
    if let Some(win) = app.get_webview_window(label) { let _ = win.show(); let _ = win.set_focus(); return; }
    let _ = WebviewWindowBuilder::new(app, label, WebviewUrl::App("index.html".into()))
        .title(title).inner_size(w, h).resizable(false)
        .decorations(false).transparent(true).shadow(true).center().build();
}

pub(crate) fn open_updater<R: tauri::Runtime>(app: &tauri::AppHandle<R>) { open_popup(app, "updater", "Software Update", 460.0, 560.0); }
pub(crate) fn open_about<R: tauri::Runtime>(app: &tauri::AppHandle<R>)   { open_popup(app, "about", "About shot2issue", 520.0, 430.0); }

/// Build (or focus) the capture HUD: a borderless, transparent, always-on-top
/// window covering one display. Returns false on native Wayland where
/// positioning / raising is unsupported (caller falls back to in-window crop).
pub(crate) fn open_overlay<R: tauri::Runtime>(app: &tauri::AppHandle<R>, display: &services::capture::Display) -> bool {
    use tauri::{WebviewUrl, WebviewWindowBuilder};
    if services::capture::is_wayland() { return false; }
    if let Some(win) = app.get_webview_window("overlay") { let _ = win.show(); let _ = win.set_focus(); return true; }
    let built = WebviewWindowBuilder::new(app, "overlay", WebviewUrl::App("index.html".into()))
        .decorations(false).transparent(true).always_on_top(true).skip_taskbar(true)
        .position(display.x as f64, display.y as f64)
        .inner_size(display.width as f64, display.height as f64)
        .focused(true).build();
    built.is_ok()
}

fn build_menu<R: tauri::Runtime>(h: &tauri::AppHandle<R>) -> tauri::Result<tauri::menu::Menu<R>> {
    use tauri::menu::{MenuBuilder, MenuItemBuilder, SubmenuBuilder};
    let about = MenuItemBuilder::with_id("about", "About shot2issue").build(h)?;
    let check = MenuItemBuilder::with_id("check-update", "Check for Updates\u{2026}").build(h)?;
    #[allow(unused_mut)]
    let mut app_sub = SubmenuBuilder::new(h, "shot2issue").item(&about).item(&check).separator();
    #[cfg(target_os = "macos")]
    { app_sub = app_sub.services().separator().hide().hide_others().show_all().separator(); }
    let app_sub = app_sub.quit().build()?;
    let edit = SubmenuBuilder::new(h, "Edit").cut().copy().paste().select_all().build()?;
    MenuBuilder::new(h).items(&[&app_sub, &edit]).build()
}

pub fn run() {
    tauri::Builder::default()
        .plugin(tauri_plugin_dialog::init())
        .plugin(tauri_plugin_shell::init())
        .plugin(tauri_plugin_store::Builder::default().build())
        .plugin(tauri_plugin_http::init())
        .plugin(tauri_plugin_updater::Builder::new().build())
        .plugin(tauri_plugin_process::init())
        .plugin(
            // Global hotkey: stock plugin works on Win/mac/X11; native Wayland
            // is unsupported (documented). The handler emits an event AND
            // kicks off the capture flow from Rust.
            tauri_plugin_global_shortcut::Builder::new()
                .with_handler(|app, _shortcut, event| {
                    if event.state() == tauri_plugin_global_shortcut::ShortcutState::Pressed {
                        let _ = app.emit("hotkey://fired", ());
                        services::capture::begin_capture_flow(app);
                    }
                })
                .build(),
        )
        .menu(|h| build_menu(h))
        .on_menu_event(|app, e| match e.id().as_ref() {
            "about" => open_about(app),
            "check-update" => open_updater(app),
            _ => {}
        })
        .on_window_event(|window, event| {
            if let WindowEvent::CloseRequested { api, .. } = event {
                if window.label() == "main" { api.prevent_close(); let _ = window.emit("app://close", ()); }
            }
        })
        .setup(|app| {
            services::tray::install(app.handle())?;       // tray icon + menu (capture/settings/quit)
            services::hotkey::register_saved(app.handle()); // read stored accelerator, register
            Ok(())
        })
        .invoke_handler(tauri::generate_handler![
            commands::capture_screen_under_cursor,
            commands::list_displays,
            commands::list_windows,
            commands::capture_window,
            commands::mac_screen_recording_authorized,
            commands::open_overlay,
            commands::close_overlay,
            commands::get_hotkey,
            commands::set_hotkey,
            commands::check_for_updates,
            commands::open_updater_window,
            commands::open_about_window,
        ])
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}

use crate::services::{capture, hotkey, updates};
use serde::Serialize;

#[derive(Debug, thiserror::Error)]
pub enum AppError {
    #[error("{0}")] Capture(String),
    #[error("{0}")] Other(String),
}
impl Serialize for AppError {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> { s.serialize_str(&self.to_string()) }
}
pub type Result<T> = std::result::Result<T, AppError>;

// ---------- Capture ----------
#[tauri::command]
pub async fn capture_screen_under_cursor() -> Result<capture::CaptureResult> { capture::screen_under_cursor() }
#[tauri::command]
pub async fn list_displays() -> Result<Vec<capture::Display>> { capture::list_displays() }
#[tauri::command]
pub async fn list_windows() -> Result<Vec<capture::WindowInfo>> { capture::list_windows() }
#[tauri::command]
pub async fn capture_window(window_id: u32) -> Result<capture::CaptureResult> { capture::capture_window(window_id) }
#[tauri::command]
pub fn mac_screen_recording_authorized() -> bool { capture::mac_screen_recording_authorized() }

// ---------- HUD overlay ----------
#[tauri::command]
pub fn open_overlay(app: tauri::AppHandle, display_id: u32) -> Result<bool> {
    let d = capture::find_display(display_id).ok_or_else(|| AppError::Capture("display not found".into()))?;
    Ok(crate::open_overlay(&app, &d))
}
#[tauri::command]
pub fn close_overlay(app: tauri::AppHandle) {
    use tauri::Manager;
    if let Some(w) = app.get_webview_window("overlay") { let _ = w.close(); }
}

// ---------- Hotkey ----------
#[tauri::command]
pub fn get_hotkey(app: tauri::AppHandle) -> String { hotkey::current(&app) }
#[tauri::command]
pub fn set_hotkey(app: tauri::AppHandle, accelerator: String) -> Result<()> {
    hotkey::reregister(&app, &accelerator).map_err(|e| AppError::Other(e.to_string()))
}

// ---------- Updates / windows (copied from curvault) ----------
#[tauri::command]
pub async fn check_for_updates() -> Result<updates::UpdateInfo> { updates::check().await.map_err(|e| AppError::Other(e.to_string())) }
#[tauri::command]
pub fn open_updater_window(app: tauri::AppHandle) { crate::open_updater(&app); }
#[tauri::command]
pub fn open_about_window(app: tauri::AppHandle) { crate::open_about(&app); }

import { useEffect, useRef, useState } from "react";
import { getCurrentWindow } from "@tauri-apps/api/window";
import { emit } from "@tauri-apps/api/event";
import { listWindows, type WindowInfo, type CaptureResult } from "../lib/api";

type Mode = "region" | "window";
interface Rect { x: number; y: number; w: number; h: number; }

export default function OverlayWindow() {
  const [mode, setMode] = useState<Mode>("region");
  const [frame, setFrame] = useState<string>(""); // data URL of the frozen screen
  const [sel, setSel] = useState<Rect | null>(null);
  const [windows, setWindows] = useState<WindowInfo[]>([]);
  const [hover, setHover] = useState<WindowInfo | null>(null);
  const drag = useRef<{ x: number; y: number } | null>(null);

  // Frameless transparent window -> transparent page bg (curvault pattern).
  useEffect(() => {
    document.documentElement.style.background = "transparent";
    document.body.style.background = "transparent";
    // The frozen frame + window list are pushed by Rust via overlay://seed.
    // (Rust seeds them when it opens this window after the hotkey.)
  }, []);

  useEffect(() => { if (mode === "window") listWindows().then(setWindows).catch(() => {}); }, [mode]);

  const onMouseDown = (e: React.MouseEvent) => { if (mode !== "region") return; drag.current = { x: e.clientX, y: e.clientY }; setSel({ x: e.clientX, y: e.clientY, w: 0, h: 0 }); };
  const onMouseMove = (e: React.MouseEvent) => {
    if (mode === "window") { setHover(pickWindow(windows, e.clientX, e.clientY)); return; }
    if (!drag.current) return;
    const { x, y } = drag.current;
    setSel({ x: Math.min(x, e.clientX), y: Math.min(y, e.clientY), w: Math.abs(e.clientX - x), h: Math.abs(e.clientY - y) });
  };
  const onMouseUp = () => { drag.current = null; };

  const confirm = async (result: CaptureResult) => { await emit("capture://annotate", result); await getCurrentWindow().close(); };
  // Esc cancels; Enter / dbl-click confirms. (handlers wired in full impl)
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") getCurrentWindow().close().catch(() => {}); };
    window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey);
  }, []);

  return (
    <div className="hud-root" onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={onMouseUp}>
      {frame && <img className="hud-frame" src={frame} alt="" />}
      <div className="hud-scrim" />
      {mode === "region" && sel && (
        <div className="hud-selection" style={{ left: sel.x, top: sel.y, width: sel.w, height: sel.h }}>
          {/* 8 .hud-handle nodes + a .hud-readout pill rendered here in full impl */}
        </div>
      )}
      {mode === "window" && hover && (
        <div className="hud-window-hint" style={{ left: hover.x, top: hover.y, width: hover.width, height: hover.height }} />
      )}
      <div className="hud-modebar">
        <button className={`icon-btn ${mode === "region" ? "active" : ""}`} onClick={() => setMode("region")} title="Region">⬚</button>
        <button className={`icon-btn ${mode === "window" ? "active" : ""}`} onClick={() => setMode("window")} title="Window">▤</button>
        <span className="hud-hint">Drag to select · Enter to confirm · Esc to cancel</span>
      </div>
    </div>
  );
}

function pickWindow(ws: WindowInfo[], x: number, y: number): WindowInfo | null {
  // Topmost window whose bounds contain the cursor (list is z-ordered).
  return ws.find((w) => x >= w.x && y >= w.y && x <= w.x + w.width && y <= w.y + w.height) ?? null;
}

// Verbatim port of curvault's UpdaterWindow.tsx. Changes:
//   const REPO_URL = "https://github.com/wa-otomia/shot2issue";
//   <h1 className="updater-title">Software Update</h1> (unchanged)
//   version line: `shot2issue · v{version}`
// All logic identical: getVersion(); check() from @tauri-apps/plugin-updater;
// State union checking|up-to-date|available|downloading|ready|error;
// update.downloadAndInstall(ev) -> Started/Progress/Finished -> ready;
// relaunch() from @tauri-apps/plugin-process; frameless DRAG via
// data-tauri-drag-region; closing animation then getCurrentWindow().close().
// Uses BrandBackdrop + BrandLogo (shot2issue variants) + the .updater-* CSS.
export { default } from "../components/UpdaterImpl"; // placeholder export shape

import { useEffect, useState } from "react";
import { getVersion } from "@tauri-apps/api/app";
import { getCurrentWindow } from "@tauri-apps/api/window";
import { open as openExternal } from "@tauri-apps/plugin-shell";
import BrandBackdrop from "../components/BrandBackdrop";
import BrandLogo from "../components/BrandLogo";

const REPO_URL = "https://github.com/wa-otomia/shot2issue";
const DRAG = { "data-tauri-drag-region": true } as const;

export default function AboutWindow() {
  const [version, setVersion] = useState("");
  const [closing, setClosing] = useState(false);
  useEffect(() => {
    document.documentElement.style.background = "transparent";
    document.body.style.background = "transparent";
    getVersion().then(setVersion).catch(() => {});
  }, []);
  const close = () => { setClosing(true); setTimeout(() => getCurrentWindow().close().catch(() => {}), 230); };
  return (
    <div className={`updater-root${closing ? " closing" : ""}`} {...DRAG}>
      <BrandBackdrop opacity={0.5} />
      <div className="updater-content about-content" {...DRAG}>
        <BrandLogo size={84} />
        <h1 className="updater-title" {...DRAG}>shot2issue</h1>
        <p className="updater-sub" {...DRAG}>Capture, annotate, and file screenshots as issues.</p>
        <div className="about-meta">
          <span><b>Version</b> v{version}</span>
          <span><b>License</b> MIT</span>
        </div>
        <div className="updater-actions">
          <button onMouseDown={(e) => e.stopPropagation()} onClick={() => openExternal(REPO_URL).catch(() => {})}>Project page</button>
          <button className="primary" onMouseDown={(e) => e.stopPropagation()} onClick={close}>Close</button>
        </div>
      </div>
    </div>
  );
}

export type View = "home" | "settings" | "annotate" | "about";

const NAV: { id: View; label: string }[] = [
  { id: "home", label: "Home" },
  { id: "settings", label: "Settings" },
  { id: "about", label: "About" },
];

export default function Sidebar({ current, onSelect }: { current: View; onSelect: (v: View) => void }) {
  return (
    <nav className="sidebar">
      <div className="brand">
        {/* Reuse curvault's C-curve mark (brandBg cyan->blue gradient) as the
            shot2issue logo so the two apps share one identity. */}
        <svg width="34" height="34" viewBox="0 0 120 120" className="brand-logo">
          <defs><linearGradient id="brandBg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#36c5ff" /><stop offset="1" stopColor="#1b4fd6" /></linearGradient></defs>
          <path d="M 86.87 33.13 A 38 38 0 1 0 86.87 86.87" fill="none" stroke="url(#brandBg)" strokeWidth="9" strokeLinecap="round" />
          <rect x="44" y="44" width="32" height="24" rx="3" fill="none" stroke="#fff" strokeWidth="5" opacity=".9" />
        </svg>
        <span className="brand-name">shot2issue</span>
      </div>
      <div className="sidebar-nav">
        {NAV.map((it) => (
