//! Screen capture service. All pixel work lives here; the webview only ever
//! receives base64 PNG strings and integer rects, never a handle to the live
//! desktop. That keeps us inside WKWebView's CORS/sandbox limits and means the
//! crop math is identical on every platform.

use std::sync::Mutex;
use base64::{engine::general_purpose::STANDARD, Engine};
use serde::Serialize;
use xcap::{Monitor, Window};

use super::{Result, ServiceError};

/// A captured monitor frame, kept in memory between the capture and the crop
/// so the overlay can request it as a data URL and the crop runs server-side.
#[derive(Clone)]
pub struct Frame {
    /// RGBA8 pixels.
    pub rgba: Vec<u8>,
    pub width: u32,
    pub height: u32,
    /// The monitor's top-left in the global virtual-desktop coordinate space
    /// (logical px). Lets the overlay window line up 1:1 with the frozen frame.
    pub origin_x: i32,
    pub origin_y: i32,
    /// device pixels per logical px for this monitor (Retina / Windows scaling).
    pub scale: f64,
}

static LAST_FRAME: Mutex<Option<Frame>> = Mutex::new(None);

/// Metadata the frontend needs to size + place the overlay window exactly over
/// the monitor it must cover. The PNG itself rides along as base64.
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct MonitorShot {
    /// base64-encoded PNG of the full monitor.
    pub png_base64: String,
    /// logical-px geometry of the captured monitor in the virtual desktop.
    pub x: i32,
    pub y: i32,
    pub width: u32,
    pub height: u32,
    pub scale: f64,
    pub monitor_name: String,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct WindowInfo {
    pub id: u32,
    pub title: String,
    pub app_name: String,
    /// bounds in logical px, virtual-desktop space (matches MonitorShot.x/y).
    pub x: i32,
    pub y: i32,
    pub width: u32,
    pub height: u32,
    pub is_minimized: bool,
}

fn encode_png(rgba: &[u8], w: u32, h: u32) -> Result<String> {
    use image::{ImageBuffer, Rgba};
    let buf: ImageBuffer<Rgba<u8>, _> = ImageBuffer::from_raw(w, h, rgba.to_vec())
        .ok_or_else(|| ServiceError::Other("capture buffer size mismatch".into()))?;
    let mut out: Vec<u8> = Vec::new();
    image::DynamicImage::ImageRgba8(buf)
        .write_to(&mut std::io::Cursor::new(&mut out), image::ImageFormat::Png)
        .map_err(|e| ServiceError::Other(format!("png encode: {e}")))?;
    Ok(STANDARD.encode(out))
}

/// Pick the monitor the OS cursor currently sits on. xcap exposes
/// `Monitor::from_point(x, y)`; we read the global cursor through it. Falls
/// back to the primary monitor if the point lookup fails (e.g. cursor between
/// monitors during a hotplug).
fn monitor_under_cursor() -> Result<Monitor> {
    // tauri's cursor_position is logical to the focused window; for a global
    // hotkey we want the true OS pointer. xcap resolves a monitor from a global
    // device-point. The point itself is supplied by the caller (see command).
    let monitors = Monitor::all().map_err(map_xcap)?;
    monitors
        .into_iter()
        .find(|m| m.is_primary().unwrap_or(false))
        .ok_or_else(|| ServiceError::Other("no monitors found".into()))
}

/// Capture the monitor that contains `(cursor_x, cursor_y)` (global device px,
/// provided by the Rust hotkey handler). Stashes the frame and returns it as a
/// MonitorShot.
pub fn capture_at(cursor_x: i32, cursor_y: i32) -> Result<MonitorShot> {
    let monitor = match Monitor::from_point(cursor_x, cursor_y) {
        Ok(m) => m,
        Err(_) => monitor_under_cursor()?,
    };
    let img = monitor.capture_image().map_err(map_xcap)?; // RgbaImage
    let (w, h) = (img.width(), img.height());
    let x = monitor.x().map_err(map_xcap)?;
    let y = monitor.y().map_err(map_xcap)?;
    let scale = monitor.scale_factor().map_err(map_xcap)? as f64;
    let rgba = img.into_raw();
    let png = encode_png(&rgba, w, h)?;

    *LAST_FRAME.lock().unwrap() = Some(Frame {
        rgba, width: w, height: h, origin_x: x, origin_y: y, scale,
    });

    Ok(MonitorShot {
        png_base64: png,
        // Report LOGICAL geometry so the overlay window (logical units) lines up.
        x, y,
        width: (w as f64 / scale).round() as u32,
        height: (h as f64 / scale).round() as u32,
        scale,
        monitor_name: monitor.name().unwrap_or_default(),
    })
}

/// List top-level windows for the window-pick UX. Bounds are reported in
/// logical px in the virtual-desktop space so the frontend can highlight them
/// over the frozen overlay.
pub fn list_windows() -> Result<Vec<WindowInfo>> {
    let wins = Window::all().map_err(map_xcap)?;
    let mut out = Vec::with_capacity(wins.len());
    for w in wins {
        let minimized = w.is_minimized().unwrap_or(false);
        if minimized { continue; }
        let title = w.title().unwrap_or_default();
        if title.trim().is_empty() { continue; } // skip chromeless helper windows
        let scale = w.current_monitor().ok()
            .and_then(|m| m.scale_factor().ok()).unwrap_or(1.0) as f64;
        out.push(WindowInfo {
            id: w.id().unwrap_or(0),
            title,
            app_name: w.app_name().unwrap_or_default(),
            x: (w.x().map_err(map_xcap)? as f64 / scale).round() as i32,
            y: (w.y().map_err(map_xcap)? as f64 / scale).round() as i32,
            width: (w.width().map_err(map_xcap)? as f64 / scale).round() as u32,
            height: (w.height().map_err(map_xcap)? as f64 / scale).round() as u32,
            is_minimized: minimized,
        });
    }
    Ok(out)
}

/// Crop the most-recent frozen frame to a rect given in LOGICAL px relative to
/// the captured monitor's top-left (i.e. overlay-window client coords). We
/// multiply by the frame scale to hit real device pixels. Returns a tight PNG.
pub fn crop_last(x: f64, y: f64, w: f64, h: f64) -> Result<String> {
    let guard = LAST_FRAME.lock().unwrap();
    let frame = guard.as_ref().ok_or_else(|| ServiceError::Other("no frozen frame".into()))?;
    let s = frame.scale;
    let (dx, dy) = ((x * s).round() as i64, (y * s).round() as i64);
    let (dw, dh) = ((w * s).round() as u32, (h * s).round() as u32);
    crop_rgba(&frame.rgba, frame.width, frame.height, dx, dy, dw, dh)
}

/// Capture a single window directly (window-pick path). xcap can capture a
/// window even when partly occluded on Win/macOS; on X11 it falls back to the
/// on-screen region. Returns a tight PNG.
pub fn capture_window(id: u32) -> Result<String> {
    let win = Window::all().map_err(map_xcap)?
        .into_iter()
        .find(|w| w.id().map(|i| i == id).unwrap_or(false))
        .ok_or_else(|| ServiceError::Other("window not found".into()))?;
    let img = win.capture_image().map_err(map_xcap)?;
    encode_png(&img.as_raw(), img.width(), img.height())
}

fn crop_rgba(rgba: &[u8], fw: u32, fh: u32, x: i64, y: i64, mut w: u32, mut h: u32) -> Result<String> {
    // Clamp to frame bounds so an over-pull at the screen edge can't panic.
    let x = x.clamp(0, fw as i64) as u32;
    let y = y.clamp(0, fh as i64) as u32;
    if x + w > fw { w = fw - x; }
    if y + h > fh { h = fh - y; }
    if w == 0 || h == 0 { return Err(ServiceError::Other("empty crop".into())); }
    let mut out = Vec::with_capacity((w * h * 4) as usize);
    for row in 0..h {
        let src = (((y + row) * fw + x) * 4) as usize;
        out.extend_from_slice(&rgba[src..src + (w * 4) as usize]);
    }
    encode_png(&out, w, h)
}

fn map_xcap(e: xcap::XCapError) -> ServiceError {
    ServiceError::Other(format!("capture failed: {e}"))
}

//! Global hotkey: register a user-rebindable accelerator that fires while the
//! app is in the background, then kick off a capture of the monitor under the
//! cursor.
//!
//! Platform reality: tauri-plugin-global-shortcut works on Windows, macOS
//! (Carbon RegisterEventHotKey — no Accessibility grant needed) and Linux/X11.
//! On native Wayland the plugin cannot grab a global key; `register` returns an
//! error which we surface so the UI can tell the user to use the tray/CLI
//! trigger instead.

use std::sync::Mutex;
use tauri::{AppHandle, Manager, Runtime};
use tauri_plugin_global_shortcut::{GlobalShortcutExt, Shortcut, ShortcutState};

use super::{Result, ServiceError};
use crate::services::overlay;

/// The currently-registered accelerator string (e.g. "CmdOrCtrl+Shift+4"),
/// so a rebind can unregister the previous one first.
static CURRENT: Mutex<Option<String>> = Mutex::new(None);

/// Default chord per platform; the user can override it in Settings and we
/// persist it via tauri-plugin-store.
pub fn default_accelerator() -> &'static str {
    if cfg!(target_os = "macos") { "Cmd+Shift+4" } else { "Ctrl+Shift+4" }
}

/// (Re)register the global capture hotkey. Unregisters any previous binding.
/// Returns Err on Wayland / when the chord is taken by another app.
pub fn register<R: Runtime>(app: &AppHandle<R>, accelerator: &str) -> Result<()> {
    let gs = app.global_shortcut();
    // Drop the old binding so a rebind doesn't leave a ghost.
    if let Some(prev) = CURRENT.lock().unwrap().take() {
        if let Ok(s) = prev.parse::<Shortcut>() { let _ = gs.unregister(s); }
    }
    let shortcut: Shortcut = accelerator
        .parse()
        .map_err(|_| ServiceError::Other(format!("invalid accelerator: {accelerator}")))?;

    let handle = app.clone();
    gs.on_shortcut(shortcut, move |_app, _sc, event| {
        // Fire on key-DOWN only (avoid double-trigger on release).
        if event.state() == ShortcutState::Pressed {
            let h = handle.clone();
            // Spawn so the plugin callback returns immediately; capture +
            // overlay creation happen off the hotkey thread.
            tauri::async_runtime::spawn(async move { trigger_capture(&h).await; });
        }
    })
    .map_err(|e| ServiceError::Other(format!("register hotkey: {e} (native Wayland is unsupported — use the tray menu)")))?;

    *CURRENT.lock().unwrap() = Some(accelerator.to_string());
    Ok(())
}

/// Read the true OS pointer position in GLOBAL device px. Tauri's
/// `cursor_position` is available off the app handle and is already in the
/// global space we feed to xcap's Monitor::from_point.
fn cursor_global<R: Runtime>(app: &AppHandle<R>) -> (i32, i32) {
    match app.cursor_position() {
        Ok(p) => (p.x.round() as i32, p.y.round() as i32),
        Err(_) => (0, 0),
    }
}

/// The full hotkey->capture->overlay flow, callable from the hotkey callback,
/// the tray menu, or a test command.
pub async fn trigger_capture<R: Runtime>(app: &AppHandle<R>) {
    let (cx, cy) = cursor_global(app);
    // Capture is CPU-bound + uses platform APIs; run it on a blocking thread.
    let shot = tauri::async_runtime::spawn_blocking(move || crate::services::capture::capture_at(cx, cy))
        .await;
    match shot {
        Ok(Ok(shot)) => {
            if let Err(e) = overlay::present(app, shot) {
                eprintln!("overlay present failed: {e}");
            }
        }
        Ok(Err(e)) => eprintln!("capture failed: {e}"),
        Err(e) => eprintln!("capture task panicked: {e}"),
    }
}

//! Overlay window management for region-crop and window-pick.
//!
//! Win/macOS/X11: a transparent, borderless, always-on-top, skip-taskbar
//! WebviewWindow is positioned exactly over the captured monitor. It paints the
//! frozen screenshot edge-to-edge and the user rubber-bands a rectangle on top.
//! macOS needs `macOSPrivateApi` (set in tauri.conf.json) for true window
//! transparency.
//!
//! Native Wayland: tao can't position a window or force always-on-top, so an
//! always-on-top fullscreen overlay is a no-op. We degrade to a NORMAL,
//! centered, decorated window that shows the captured image and runs the exact
//! same crop UI against the static bitmap.

use std::sync::Mutex;
use tauri::{AppHandle, Emitter, LogicalPosition, LogicalSize, Manager, Runtime,
            WebviewUrl, WebviewWindowBuilder};

use super::{Result, ServiceError};
use crate::services::capture::MonitorShot;

/// The shot the overlay is currently showing; the overlay webview fetches it
/// via the `get_overlay_shot` command once it mounts (avoids cramming a multi-MB
/// base64 PNG into the window URL).
static PENDING_SHOT: Mutex<Option<MonitorShot>> = Mutex::new(None);

pub fn take_pending_shot() -> Option<MonitorShot> {
    PENDING_SHOT.lock().unwrap().take()
}

fn is_wayland() -> bool {
    cfg!(target_os = "linux")
        && std::env::var("WAYLAND_DISPLAY").is_ok()
        && std::env::var("GDK_BACKEND").map(|b| b != "x11").unwrap_or(true)
}

/// Present the captured shot for cropping. Branches on platform.
pub fn present<R: Runtime>(app: &AppHandle<R>, shot: MonitorShot) -> Result<()> {
    *PENDING_SHOT.lock().unwrap() = Some(shot);
    if is_wayland() {
        present_windowed(app)
    } else {
        present_overlay(app)
    }
}

/// Win/macOS/X11: spawn (or reuse) the fullscreen transparent overlay placed
/// over the captured monitor.
fn present_overlay<R: Runtime>(app: &AppHandle<R>) -> Result<()> {
    let shot = PENDING_SHOT.lock().unwrap();
    let shot = shot.as_ref().ok_or_else(|| ServiceError::Other("no pending shot".into()))?;
    let (x, y) = (shot.x, shot.y);
    let (w, h) = (shot.width as f64, shot.height as f64);
    drop(shot);

    if let Some(win) = app.get_webview_window("overlay") {
        // Reuse: reposition over the (possibly different) monitor and re-emit.
        let _ = win.set_position(LogicalPosition::new(x as f64, y as f64));
        let _ = win.set_size(LogicalSize::new(w, h));
        let _ = win.show();
        let _ = win.set_focus();
        let _ = win.emit("overlay://refresh", ());
        return Ok(());
    }

    let win = WebviewWindowBuilder::new(app, "overlay", WebviewUrl::App("index.html".into()))
        .title("shot2issue capture")
        .inner_size(w, h)
        .position(x as f64, y as f64)
        .resizable(false)
        .decorations(false)
        .transparent(true)        // needs macOSPrivateApi on macOS
        .always_on_top(true)
        .skip_taskbar(true)       // no taskbar/dock entry for the overlay
        .shadow(false)
        .focused(true)
        .visible(true)
        .build()
        .map_err(|e| ServiceError::Other(format!("overlay window: {e}")))?;

    // Belt-and-suspenders: some WMs ignore the builder flag.
    let _ = win.set_always_on_top(true);
    // Cover the whole monitor including any OS panel. fullscreen(true) is
    // avoided on macOS (it animates into a Space); exact size+pos is crisper.
    #[cfg(target_os = "macos")]
    let _ = win.set_fullscreen(false);
    Ok(())
}

/// Native Wayland degrade: a normal decorated window that crops the static
/// image. No positioning / always-on-top is attempted.
fn present_windowed<R: Runtime>(app: &AppHandle<R>) -> Result<()> {
    if let Some(win) = app.get_webview_window("overlay") {
        let _ = win.show();
        let _ = win.set_focus();
        let _ = win.emit("overlay://refresh", ());
        return Ok(());
    }
    WebviewWindowBuilder::new(app, "overlay", WebviewUrl::App("index.html".into()))
        .title("Crop screenshot")
        .inner_size(1100.0, 720.0)
        .resizable(true)
        .decorations(true)
        .center()
        .build()
        .map_err(|e| ServiceError::Other(format!("crop window: {e}")))?;
    Ok(())
}

/// Make the overlay click-through (true) or interactive (false). The frontend
/// flips this so the dimmed region doesn't eat clicks meant for other apps in
/// window-pick mode, then turns it back on to draw the rubber-band.
pub fn set_click_through<R: Runtime>(app: &AppHandle<R>, ignore: bool) -> Result<()> {
    if let Some(win) = app.get_webview_window("overlay") {
        win.set_ignore_cursor_events(ignore)
            .map_err(|e| ServiceError::Other(format!("ignore cursor events: {e}")))?;
    }
    Ok(())
}

/// Close the overlay (on confirm/cancel/Esc).
pub fn dismiss<R: Runtime>(app: &AppHandle<R>) {
    if let Some(win) = app.get_webview_window("overlay") {
        let _ = win.close();
    }
}

//! Capture/hotkey/overlay command surface. Renderer invoke() calls enter here.

use crate::services::{capture, hotkey, overlay};
use crate::services::Result;
use tauri::AppHandle;

// ---------- Hotkey ----------

#[tauri::command]
pub fn get_default_accelerator() -> String {
    hotkey::default_accelerator().to_string()
}

/// (Re)bind the global capture hotkey. Err on Wayland / chord-in-use.
#[tauri::command]
pub fn set_capture_hotkey(app: AppHandle, accelerator: String) -> Result<()> {
    hotkey::register(&app, &accelerator)
}

/// Manual trigger (tray menu / button / test) — same path as the hotkey.
#[tauri::command]
pub async fn trigger_capture(app: AppHandle) -> Result<()> {
    hotkey::trigger_capture(&app).await;
    Ok(())
}

// ---------- Capture ----------

/// Capture the monitor under the cursor right now (used when triggered from a
/// foreground button rather than the background hotkey).
#[tauri::command]
pub async fn capture_current_monitor(app: AppHandle) -> Result<capture::MonitorShot> {
    let p = app.cursor_position().map(|p| (p.x as i32, p.y as i32)).unwrap_or((0, 0));
    tauri::async_runtime::spawn_blocking(move || capture::capture_at(p.0, p.1))
        .await
        .map_err(|e| crate::services::ServiceError::Other(format!("join: {e}")))?
}

/// Pull the frozen shot the overlay should paint (called once the overlay
/// webview mounts).
#[tauri::command]
pub fn get_overlay_shot() -> Option<capture::MonitorShot> {
    overlay::take_pending_shot()
}

/// List top-level windows for window-pick.
#[tauri::command]
pub async fn list_windows() -> Result<Vec<capture::WindowInfo>> {
    tauri::async_runtime::spawn_blocking(capture::list_windows)
        .await
        .map_err(|e| crate::services::ServiceError::Other(format!("join: {e}")))?
}

/// Capture one window to a tight PNG (window-pick confirm).
#[tauri::command]
pub async fn capture_window(id: u32) -> Result<String> {
    tauri::async_runtime::spawn_blocking(move || capture::capture_window(id))
        .await
        .map_err(|e| crate::services::ServiceError::Other(format!("join: {e}")))?
}

/// Crop the frozen frame to a logical-px rect relative to the overlay client
/// area. Returns a tight base64 PNG.
#[tauri::command]
pub async fn crop_region(x: f64, y: f64, width: f64, height: f64) -> Result<String> {
    tauri::async_runtime::spawn_blocking(move || capture::crop_last(x, y, width, height))
        .await
        .map_err(|e| crate::services::ServiceError::Other(format!("join: {e}")))?
}

// ---------- Overlay ----------

#[tauri::command]
pub fn overlay_set_click_through(app: AppHandle, ignore: bool) -> Result<()> {
    overlay::set_click_through(&app, ignore)
}

#[tauri::command]
pub fn overlay_dismiss(app: AppHandle) {
    overlay::dismiss(&app);
}

/// After crop/window-pick produces a PNG, hand it to the editor exactly like
/// the extension's background.ts stageAndOpen: stash the data URL + metadata
/// and open (or focus) the `editor` window. Implemented in the editor staging
/// service; declared here so the renderer has one entry point.
#[tauri::command]
pub fn open_editor_with(app: AppHandle, png_base64: String) -> Result<()> {
    crate::services::editor_stage::stage_and_open(&app, png_base64)
}

// Capture flow: invoke() wrappers + the hotkey->overlay->crop->editor pipeline.
// Single chokepoint, mirroring curvault's src/lib/api.ts convention.

import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";

export interface MonitorShot {
  pngBase64: string;
  x: number; y: number;
  width: number; height: number;
  scale: number;
  monitorName: string;
}

export interface WindowInfo {
  id: number;
  title: string;
  appName: string;
  x: number; y: number; width: number; height: number;
  isMinimized: boolean;
}

// ---- hotkey ----
export const getDefaultAccelerator = (): Promise<string> =>
  invoke("get_default_accelerator");
/** Returns rejected promise on Wayland / chord-in-use; caller shows the reason. */
export const setCaptureHotkey = (accelerator: string): Promise<void> =>
  invoke("set_capture_hotkey", { accelerator });
export const triggerCapture = (): Promise<void> => invoke("trigger_capture");

// ---- capture ----
export const captureCurrentMonitor = (): Promise<MonitorShot> =>
  invoke("capture_current_monitor");
export const getOverlayShot = (): Promise<MonitorShot | null> =>
  invoke("get_overlay_shot");
export const listWindows = (): Promise<WindowInfo[]> => invoke("list_windows");
export const captureWindow = (id: number): Promise<string> =>
  invoke("capture_window", { id });
/** rect is in LOGICAL px relative to the overlay client area. */
export const cropRegion = (x: number, y: number, width: number, height: number): Promise<string> =>
  invoke("crop_region", { x, y, width, height });

// ---- overlay ----
export const overlaySetClickThrough = (ignore: boolean): Promise<void> =>
  invoke("overlay_set_click_through", { ignore });
export const overlayDismiss = (): Promise<void> => invoke("overlay_dismiss");
export const openEditorWith = (pngBase64: string): Promise<void> =>
  invoke("open_editor_with", { pngBase64 });

// ---- events the overlay window listens for ----
/** Re-emitted when the same overlay window is reused for a fresh capture. */
export const onOverlayRefresh = (cb: () => void): Promise<UnlistenFn> =>
  listen("overlay://refresh", () => cb());

// ---- orchestration (runs inside the overlay window) ----

export type CropResult = { pngBase64: string } | { cancelled: true };

/**
 * Confirm a region selection: ask Rust to crop the frozen frame, hand the PNG
 * to the editor, and close the overlay. `rect` is in CSS px of the overlay
 * client area, which equals logical monitor px (overlay is sized 1:1).
 */
export async function confirmRegion(rect: { x: number; y: number; w: number; h: number }): Promise<void> {
  const png = await cropRegion(rect.x, rect.y, rect.w, rect.h);
  await openEditorWith(png);
  await overlayDismiss();
}

