import { useEffect, useRef, useState, useCallback } from "react";
import {
  getOverlayShot, listWindows, confirmRegion, confirmWindow, cancelCapture,
  overlaySetClickThrough, onOverlayRefresh,
  type MonitorShot, type WindowInfo,
} from "../lib/capture";

type Mode = "region" | "window";
type Rect = { x: number; y: number; w: number; h: number };

export default function Overlay() {
  const [shot, setShot] = useState<MonitorShot | null>(null);
  const [mode, setMode] = useState<Mode>("region");
  const [rect, setRect] = useState<Rect | null>(null);
  const [windows, setWindows] = useState<WindowInfo[]>([]);
  const [hovered, setHovered] = useState<WindowInfo | null>(null);
  const dragStart = useRef<{ x: number; y: number } | null>(null);

  const load = useCallback(async () => {
    const s = await getOverlayShot();
    setShot(s); setRect(null); setHovered(null);
  }, []);

  // Initial mount + reuse refresh.
  useEffect(() => { void load(); }, [load]);
  useEffect(() => {
    const p = onOverlayRefresh(() => void load());
    return () => { p.then((f) => f()); };
  }, [load]);

  // Keyboard: Esc cancels, Enter confirms a pending region, Tab toggles mode.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") void cancelCapture();
      else if (e.key === "Enter" && rect && rect.w > 2 && rect.h > 2) void confirmRegion(rect);
      else if (e.key === "Tab") { e.preventDefault(); toggleMode(); }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [rect]);

  const toggleMode = useCallback(async () => {
    const next = mode === "region" ? "window" : "region";
    setMode(next);
    if (next === "window" && windows.length === 0) setWindows(await listWindows());
  }, [mode, windows.length]);

  // --- region drag handlers (overlay is sized 1:1 to logical monitor px, so
  //     clientX/clientY already equal the crop rect coords Rust expects) ---
  const onDown = (e: React.MouseEvent) => {
    if (mode !== "region") return;
    dragStart.current = { x: e.clientX, y: e.clientY };
    setRect({ x: e.clientX, y: e.clientY, w: 0, h: 0 });
  };
  const onMove = (e: React.MouseEvent) => {
    if (mode === "region" && dragStart.current) {
      const s = dragStart.current;
      setRect({
        x: Math.min(s.x, e.clientX), y: Math.min(s.y, e.clientY),
        w: Math.abs(e.clientX - s.x), h: Math.abs(e.clientY - s.y),
      });
    } else if (mode === "window") {
      // Highlight the topmost window whose bounds contain the cursor. Window
      // bounds are virtual-desktop logical px; subtract this monitor's origin.
      const px = e.clientX + (shot?.x ?? 0), py = e.clientY + (shot?.y ?? 0);
      const hit = windows.find((w) =>
        px >= w.x && px <= w.x + w.width && py >= w.y && py <= w.y + w.height);
      setHovered(hit ?? null);
    }
  };
  const onUp = () => { dragStart.current = null; };

  const onClickWindow = () => { if (mode === "window" && hovered) void confirmWindow(hovered.id); };

  if (!shot) return null;
  const img = `data:image/png;base64,${shot.pngBase64}`;
  // window-highlight rect, translated into overlay-local coords:
  const hi = hovered && {
    left: hovered.x - shot.x, top: hovered.y - shot.y,
    width: hovered.width, height: hovered.height,
  };

  return (
    <div className="overlay-root" onMouseDown={onDown} onMouseMove={onMove}
         onMouseUp={onUp} onClick={onClickWindow}>
      <img className="overlay-frame" src={img} draggable={false} alt="" />
      <div className="overlay-dim" />{/* full dim; the selection punches a hole */}
      {mode === "region" && rect && (
        <div className="overlay-sel"
             style={{ left: rect.x, top: rect.y, width: rect.w, height: rect.h }}>
          <span className="overlay-size">{Math.round(rect.w)} × {Math.round(rect.h)}</span>
        </div>
      )}
      {mode === "window" && hi && (
        <div className="overlay-winhi" style={hi as React.CSSProperties} />
      )}
      <div className="overlay-hint">
        {mode === "region"
          ? "Drag to select · Enter to confirm · Tab for window pick · Esc to cancel"
          : "Click a window · Tab for region · Esc to cancel"}
      </div>
    </div>
  );
}

