            let accel = services::settings::capture_hotkey(app.handle())
                .unwrap_or_else(|| services::hotkey::default_accelerator().to_string());
            if let Err(e) = services::hotkey::register(app.handle(), &accel) {
                eprintln!("global hotkey not registered: {e}");
