// ---- DESKTOP-FRIENDLY connect: replaces connectViaCallbackCapture (chrome.tabs) ----
// Uses the Rust loopback server instead of watching a tab URL.
export async function connect(oauth: OAuthLoopbackPort, shell: ShellPort): Promise<AiAuth> {
  const { verifier, challenge } = await genPkce();
  const state = randomState();
  const { redirectUri, callbackUrl } = await oauth.capture();
  await setPendingAuth({ verifier, state, redirectUri, createdAt: NOW() });
  await shell.openExternal(buildAuthorizeUrl({ redirectUri, challenge, state }));
  const url = await callbackUrl; // resolves when the Rust server receives /auth/callback
  const parsed = parseRedirect(url);
  const pending = await getPendingAuth();
  if (!pending) throw new Error('No sign-in in progress.');
  if (parsed.state && pending.state && parsed.state !== pending.state) throw new Error('State mismatch.');
  const auth = await exchangeCode({ code: parsed.code, verifier: pending.verifier, redirectUri: pending.redirectUri });
  await clearPendingAuth();
  auth.models = await fetchModels(auth); auth.model = auth.models[0] || DEFAULT_MODELS[0];
  await setAiAuth(auth);
  return auth;
}

