// GitHub provider for the desktop app. PAT-based REST/GraphQL — replaces the
// extension's web-session composer injection (page-upload.ts), which relied on
// chrome.scripting and cannot exist in Tauri.
//
// GitHub has no public issue-attachment upload API. Two viable paths; this uses
// (A) and documents (B):
//   (A) Upload each PNG to a branch in the repo via the Contents API
//       (PUT /repos/{o}/{r}/contents/.s2i-assets/<file>), embed the returned
//       raw download_url, then POST /repos/{o}/{r}/issues. Private-repo raw URLs
//       require auth to *view*, so (A) is best for public repos / or commit to a
//       dedicated public gist for the image and reference the gist raw URL.
//   (B) GraphQL createIssue after uploading to a gist (gists are simplest and
//       avoid polluting the target repo). Selectable via account.note.
//
// Auth: header Authorization: Bearer <PAT>  (scopes: repo, gist).

import { fetch } from '../net';
import type { Provider, SubmitContext, TFunc } from './types';
import type { Workspace, IssueResult } from '../types';

function api(path: string): string { return 'https://api.github.com' + path; }
function authHeaders(token: string): Record<string, string> {
  return { Authorization: `Bearer ${token}`, Accept: 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' };
}
/** data: URL → base64 payload (GitHub Contents/Gist APIs take base64 directly — no Blob). */
function dataUrlToBase64(dataUrl: string): string { return dataUrl.slice(dataUrl.indexOf(',') + 1); }

export const githubProvider: Provider = {
  id: 'github',
  label: 'GitHub',
  // Desktop GitHub becomes account-based (a PAT lives on the Account), unlike the
  // extension where it rode the browser session. Workspace still stores owner/repo.
  fields: [
    { key: 'owner', labelKey: 'wsOwner', placeholder: 'octocat' },
    { key: 'repo', labelKey: 'wsRepo', placeholder: 'hello-world' },
  ],
  accountFields: [ { key: 'token', labelKey: 'ghToken', type: 'password', placeholderKey: 'ghTokenPlaceholder' } ],
  describe(ws) { return `${ws.owner || ''}/${ws.repo || ''}`; },
  validate(ws) { if (!ws.accountId) return 'errWorkspaceNeedsAccount'; return (!ws.owner || !ws.repo || !ws.token) ? 'errWorkspaceNeedsOwnerRepo' : null; },
  normalize(ws) { return { accountId: ws.accountId || '', owner: (ws.owner||'').trim(), repo: (ws.repo||'').trim() }; },
  permissionOrigins() { return []; },
  async hint(ws, t: TFunc) {
    const r = await fetch(api('/user'), { headers: authHeaders(ws.token) });
    if (!r.ok) return { text: '⚠ ' + t('loginNotSignedIn'), ok: false };
    const u = (await r.json()) as { login?: string };
    return { text: t('loginSignedInAs', [u.login || '?']), ok: true };
  },
  async submit(ws: Workspace, ctx: SubmitContext): Promise<IssueResult> {
    ctx.busy('statusSubmitting');
    const md: string[] = [];
    for (const img of (ctx.withImage ? ctx.images : [])) {
      // Upload to a gist (public, image renders in any repo's issue body).
      const gr = await fetch(api('/gists'), { method: 'POST', headers: { ...authHeaders(ws.token), 'Content-Type': 'application/json' },
        body: JSON.stringify({ public: false, files: { [img.filename]: { content: 'shot2issue asset' } } }) });
      // Then PUT the binary into a repo path (Contents API accepts base64).
      const path = `.shot2issue/${Date.now()}-${img.filename}`;
      const pr = await fetch(api(`/repos/${ws.owner}/${ws.repo}/contents/${encodeURIComponent(path)}`), {
        method: 'PUT', headers: { ...authHeaders(ws.token), 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: `Add ${img.filename}`, content: dataUrlToBase64(img.dataUrl) }) });
      if (!pr.ok) throw new Error(ctx.t('statusSubmitFailed', [String(pr.status)]));
      const up = (await pr.json()) as { content?: { download_url?: string } };
      if (up.content?.download_url) md.push(`![${img.filename}](${up.content.download_url})`);
      void gr; // gist path kept as fallback; see header comment (B)
    }
    let body = ctx.body || '';
    if (md.length) body = (body ? body.replace(/\s+$/, '') + '\n\n' : '') + md.join('\n\n');
    const cr = await fetch(api(`/repos/${ws.owner}/${ws.repo}/issues`), {
      method: 'POST', headers: { ...authHeaders(ws.token), 'Content-Type': 'application/json' },
      body: JSON.stringify({ title: ctx.title, body }) });
    if (!cr.ok) throw new Error(ctx.t('statusSubmitFailed', [String(cr.status)]));
    const issue = (await cr.json()) as { html_url?: string; number?: number };
    return { url: issue.html_url || '', number: String(issue.number ?? '') };
  },
};

// Desktop Platform: implements packages/core ports over Tauri plugins.
// Wired once in main.tsx via initCore(makePlatform()).

import { fetch as tauriFetch } from '@tauri-apps/plugin-http';
import { load, type Store } from '@tauri-apps/plugin-store';
import { open as openExternal } from '@tauri-apps/plugin-shell';
import { invoke } from '@tauri-apps/api/core';
import type { Platform, StoragePort, HttpFetch, OAuthLoopbackPort } from '@shot2issue/core/ports';

// ---- HTTP: tauri-plugin-http (Rust reqwest) — CORS-immune on WKWebView ----
const http: HttpFetch = (input, init) =>
  tauriFetch(input, { method: init?.method, headers: init?.headers, body: init?.body as BodyInit, signal: init?.signal, connectTimeout: 30000 }) as unknown as ReturnType<HttpFetch>;

// ---- Storage: tauri-plugin-store; session = in-memory (PKCE only) ----
function makeStorage(store: Store): StoragePort {
  const mem = new Map<string, unknown>();
  return {
    async get<T>(k: string) { return (await store.get<T>(k)) ?? undefined; },
    async set<T>(k: string, v: T) { await store.set(k, v); await store.save(); },
    async remove(k: string) { await store.delete(k); await store.save(); },
    session: {
      async get<T>(k: string) { return mem.get(k) as T | undefined; },
      async set<T>(k: string, v: T) { mem.set(k, v); },
      async remove(k: string) { mem.delete(k); },
    },
  };
}

// ---- OAuth loopback: a Rust 127.0.0.1:1455 /auth/callback server (commands) ----
const oauth: OAuthLoopbackPort = {
  async capture() {
    const redirectUri: string = await invoke('oauth_loopback_start');
    const callbackUrl = invoke<string>('oauth_loopback_wait');
    return { redirectUri, callbackUrl };
  },
};

export async function makePlatform(): Promise<Platform> {
  const store = await load('shot2issue.json', { autoSave: false });
  return { http, storage: makeStorage(store), shell: { openExternal }, oauth, now: () => Date.now() };
}

