// React annotation surface. Owns the canvas + interaction state (what editor.ts
// held as module globals) and calls the verbatim engine for all rendering and
// geometry. No chrome.*, no DOM-id lookups.

import { useEffect, useRef } from 'react';
import * as eng from '@shot2issue/core/canvas';
import type { Op, Attachment } from '@shot2issue/core';
import { useAnnotator } from './useAnnotator';

export interface AnnotationCanvasProps {
  attachment: Attachment;
  tool: string;
  prefs: { color: string; strokeColor: string; strokeWidth: number; width: number; fontSize: number };
  onOpsChange(ops: Op[]): void;       // persist (debounced) back to pendingShots
  onCrop(dataUrl: string, ops: Op[]): void;
}

export default function AnnotationCanvas(props: AnnotationCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const textRef = useRef<HTMLTextAreaElement>(null);
  // useAnnotator wires mousedown/move/up + key handling onto the canvas, mirroring
  // editor.ts's handlers, but stores state in refs instead of module-level lets.
  const a = useAnnotator({ canvasRef, textRef, ...props });
  useEffect(() => a.loadImage(props.attachment.dataUrl), [props.attachment.id]);
  return (
    <div className="canvas-wrap" ref={a.wrapRef}>
      <canvas ref={canvasRef} onMouseDown={a.onMouseDown} />
      <textarea ref={textRef} className="text-input" wrap="off" rows={1} spellCheck={false} style={{ display: 'none' }} />
      {a.cropRect && (
        <div className="crop-actions" style={a.cropBarStyle}>
          <button className="primary" onClick={a.applyCrop}>Apply</button>
          <button className="ghost" onClick={a.cancelCrop}>Cancel</button>
        </div>
      )}
    </div>
  );
}
void eng; // engine functions are called inside useAnnotator

// Interaction state + event wiring for AnnotationCanvas. Mirrors editor.ts's
// pointer/keyboard handlers, but the geometry & drawing come from
// @shot2issue/core/canvas. State that editor.ts kept in module-level `let`s
// (drawing, selected, dragMode, dragHandle, dragOrig, cropRect, cropOrig,
// pendingTextOp) lives in refs here.

import { useRef, useCallback, type RefObject } from 'react';
import * as eng from '@shot2issue/core/canvas';
import type { Op } from '@shot2issue/core';

export function useAnnotator(args: {
  canvasRef: RefObject<HTMLCanvasElement>;
  textRef: RefObject<HTMLTextAreaElement>;
  tool: string;
  prefs: { color: string; strokeColor: string; strokeWidth: number; width: number; fontSize: number };
  onOpsChange(ops: Op[]): void;
  onCrop(dataUrl: string, ops: Op[]): void;
}) {
  const opsRef = useRef<Op[]>([]);
  const drawingRef = useRef<Op | null>(null);
  const selectedRef = useRef<Op | null>(null);
  const baseImg = useRef(new Image());
  const wrapRef = useRef<HTMLDivElement>(null);
  // … crop/drag/text refs mirroring editor.ts …

  const redraw = useCallback(() => {
    const c = args.canvasRef.current?.getContext('2d'); if (!c) return;
    eng.renderOps(c, baseImg.current, c.canvas.width, c.canvas.height, opsRef.current);
    if (drawingRef.current && drawingRef.current.tool !== 'crop') eng.drawOne(c, baseImg.current, drawingRef.current);
    // selection chrome + crop overlay drawn here (ported from editor.ts:1444/1474)
  }, [args.canvasRef]);

  const onMouseDown = useCallback((e: React.MouseEvent) => { /* port of editor.ts canvas mousedown:1225 */ }, []);
  // window-level mousemove/mouseup/keydown attached via useEffect (omitted here)

  const loadImage = useCallback((dataUrl: string) => {
    baseImg.current.onload = () => { const cv = args.canvasRef.current!; cv.width = baseImg.current.naturalWidth; cv.height = baseImg.current.naturalHeight; redraw(); };
    baseImg.current.src = dataUrl;
  }, [args.canvasRef, redraw]);

  const applyCrop = useCallback(() => { /* port of editor.ts applyCrop:1192 using eng.offsetOp/opIntersects */ }, []);
  const cancelCrop = useCallback(() => { /* … */ }, []);

  return { wrapRef, onMouseDown, loadImage, applyCrop, cancelCrop, cropRect: null as eng.Rect | null, cropBarStyle: {} as React.CSSProperties };
}

// Editor page: toolbar + AnnotationCanvas + issue form + AI controls.
// Curvault design language (cards, gradient .primary buttons, glass).

import { useEffect, useState } from 'react';
import AnnotationCanvas from './AnnotationCanvas';
import { getProvider } from '@shot2issue/core/providers';
import { generateTitle, generateComplaint, transcribeAudio, connect } from '@shot2issue/core/ai';
import { getConfig, getPendingShots, accountFor, patchEditorPrefs, getEditorPrefs } from '@shot2issue/core';
import { renderAttachmentToDataUrl, downscaleDataUrl } from '@shot2issue/core/canvas';
import { t } from '@shot2issue/core/i18n';
import type { Config, Attachment, Workspace, Op, EditorPrefs } from '@shot2issue/core';

export default function EditorView() {
  const [config, setConfig] = useState<Config | null>(null);
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [active, setActive] = useState(0);
  const [tool, setTool] = useState('rect');
  const [prefs, setPrefs] = useState<EditorPrefs>();
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [status, setStatus] = useState('');

  useEffect(() => { (async () => {
    setConfig(await getConfig()); setPrefs(await getEditorPrefs());
    const shots = await getPendingShots(); if (shots) setAttachments(shots.attachments);
  })(); }, []);

  const submit = async (withImage: boolean) => {
    if (!config) return;
    const ws = config.workspaces.find(w => w.id /* selected */) as Workspace;
    const merged = (() => { const acct = accountFor(config, ws); return acct ? { ...ws, baseUrl: acct.baseUrl, token: acct.token } : ws; })();
    const provider = getProvider(merged.kind || 'github');
    const images = withImage ? await Promise.all(attachments.map(async (a, i) => ({ dataUrl: await renderAttachmentToDataUrl(a.dataUrl, a.ops), filename: `shot-${i+1}-${Date.now()}.png` }))) : [];
    const acct = accountFor(config, ws);
    const issue = await provider.submit(merged, { title, body, images, withImage: withImage && images.length>0, dataUrl: images[0]?.dataUrl||'', filename: images[0]?.filename||'shot.png', account: acct ? { id: acct.id, kind: acct.kind, baseUrl: acct.baseUrl, token: acct.token } : undefined, t, busy: (k) => setStatus(t(k)) });
    setStatus(issue.number ? t('statusCreated', [issue.number]) : t('statusCreatedNoNumber'));
  };

  // AI title: same generateTitle as the extension; images downscaled via the engine.
  const aiImages = () => Promise.all(attachments.map(async a => downscaleDataUrl(await renderAttachmentToDataUrl(a.dataUrl, a.ops))));

  return ( <div className="content editor"> {/* toolbar, <AnnotationCanvas/>, form, AI buttons, status */} </div> );
}

//! Codex OAuth loopback. Replaces the extension's chrome.tabs ?code= capture.
//! Binds 127.0.0.1:1455, captures the /auth/callback request line, hands the
//! full callback URL back to the frontend (which exchanges the code via the
//! injected Rust-reqwest fetch).

use std::io::{BufRead, BufReader, Write};
use std::net::TcpListener;
use std::sync::Mutex;
use tauri::State;

pub const REDIRECT_URI: &str = "http://127.0.0.1:1455/auth/callback";

#[derive(Default)]
pub struct Loopback(pub Mutex<Option<TcpListener>>);

#[tauri::command]
pub fn oauth_loopback_start(state: State<Loopback>) -> Result<String, String> {
    let listener = TcpListener::bind("127.0.0.1:1455").map_err(|e| e.to_string())?;
    *state.0.lock().unwrap() = Some(listener);
    Ok(REDIRECT_URI.to_string())
}

/// Blocks (on a worker thread; Tauri commands run off the UI thread) until the
/// browser hits the callback, then returns the full URL incl. ?code=&state=.
#[tauri::command]
pub fn oauth_loopback_wait(state: State<Loopback>) -> Result<String, String> {
    let listener = state.0.lock().unwrap().take().ok_or("loopback not started")?;
    for stream in listener.incoming() {
        let mut stream = stream.map_err(|e| e.to_string())?;
        let mut line = String::new();
        BufReader::new(&stream).read_line(&mut line).map_err(|e| e.to_string())?;
        // line = "GET /auth/callback?code=...&state=... HTTP/1.1"
        if let Some(path) = line.split_whitespace().nth(1) {
            let _ = stream.write_all(b"HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<html><body>Sign-in complete. You can close this window.</body></html>");
            if path.starts_with("/auth/callback") {
                return Ok(format!("http://127.0.0.1:1455{path}"));
            }
        }
    }
    Err("loopback closed".into())
}

